require __DIR__.'/config.php'; require __DIR__.'/database_upgrade.php'; require __DIR__.'/customer_layout.php'; try{$pdo=db();apply_database_upgrade($pdo);}catch(Throwable $e){exit('Directory unavailable.');}$page=$_GET['page']??'home';
function go(string $url):never{header('Location: '.$url);exit;} function cats(PDO $p):array{return $p->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();} function services(PDO $p,int $id):array{$q=$p->prepare('SELECT bs.*,s.name FROM business_services bs JOIN services s ON s.id=bs.service_id WHERE bs.business_id=?');$q->execute([$id]);return $q->fetchAll();}
function category_photo(string $name):string{$photos=['Automotive'=>'https://images.unsplash.com/photo-1635352124120-739339ec9ac1?auto=format&fit=crop&w=960&q=82','Beauty & Wellness'=>'https://images.unsplash.com/photo-1560066984-138dadb4c035?auto=format&fit=crop&w=960&q=82','Clothing'=>'https://images.unsplash.com/photo-1761090617068-f1b3257d27ad?auto=format&fit=crop&w=960&q=82','Education'=>'https://images.unsplash.com/photo-1602145095452-aba06946ed05?auto=format&fit=crop&w=960&q=82','Electronics'=>'https://images.unsplash.com/photo-1498049794561-7780e7231661?auto=format&fit=crop&w=960&q=82','Food & Beverage'=>'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=960&q=82','Home Services'=>'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=960&q=82','Other'=>'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=960&q=82','Printing Services'=>'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Kevin%2C_a_large_format_printer_operator.jpg/500px-Kevin%2C_a_large_format_printer_operator.jpg','Professional Services'=>'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=960&q=82','Repair Services'=>'https://images.unsplash.com/photo-1581092921461-eab62e97a780?auto=format&fit=crop&w=960&q=82','Retail'=>'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=960&q=82'];return $photos[$name]??$photos['Other'];}function listing_open_now(PDO $p,array $b):bool{return ($b['business_status']??'open')==='open'&&business_open_now($p,(int)$b['id']);}
function list_businesses(PDO $p):array{$w=["b.status='approved'"];$v=[];$text=trim($_GET['q']??'');if($text!==''){$w[]='(b.name LIKE ? OR b.description LIKE ? OR EXISTS(SELECT 1 FROM business_services bs JOIN services s ON s.id=bs.service_id WHERE bs.business_id=b.id AND s.name LIKE ?) OR EXISTS(SELECT 1 FROM products p WHERE p.business_id=b.id AND p.name LIKE ?))';array_push($v,"%$text%","%$text%","%$text%","%$text%");}if(($x=(int)($_GET['category']??0))){$w[]='b.category_id=?';$v[]=$x;}if(($x=trim($_GET['area']??''))!==''){$w[]='(b.barangay LIKE ? OR b.district LIKE ? OR b.city LIKE ?)';array_push($v,"%$x%","%$x%","%$x%");}if(($_GET['verified']??'')==='1')$w[]='b.is_verified=1';if(($_GET['open']??'')==='1'){$w[]="b.business_status='open' AND EXISTS(SELECT 1 FROM business_hours h WHERE h.business_id=b.id AND h.day_of_week=? AND h.is_closed=0 AND h.opens<=? AND h.closes>?)";$now=date('H:i:s');$v[]=(int)date('w');$v[]=$now;$v[]=$now;};if(($_GET['contact']??'')==='1')$w[]="b.contact_phone<>''";if(($_GET['map']??'')==='1')$w[]='b.is_demo=0 AND b.latitude BETWEEN -90 AND 90 AND b.longitude BETWEEN -180 AND 180';if(($_GET['services']??'')==='1')$w[]='EXISTS(SELECT 1 FROM business_services bs WHERE bs.business_id=b.id)';if(($x=(int)($_GET['rating']??0))>0){$w[]='(SELECT COALESCE(AVG(rr.rating),0) FROM reviews rr WHERE rr.business_id=b.id AND rr.status="visible")>=?';$v[]=$x;}if(($min=filter_input(INPUT_GET,'price_min',FILTER_VALIDATE_FLOAT))!==false&&$min!==null){$w[]='EXISTS(SELECT 1 FROM business_services bs WHERE bs.business_id=b.id AND bs.price>=?)';$v[]=$min;}if(($max=filter_input(INPUT_GET,'price_max',FILTER_VALIDATE_FLOAT))!==false&&$max!==null){$w[]='EXISTS(SELECT 1 FROM business_services bs WHERE bs.business_id=b.id AND bs.price<=?)';$v[]=$max;}$lat=filter_input(INPUT_GET,'lat',FILTER_VALIDATE_FLOAT);$lng=filter_input(INPUT_GET,'lng',FILTER_VALIDATE_FLOAT);$distance='NULL distance_km';if($lat!==false&&$lat!==null&&$lng!==false&&$lng!==null&&abs($lat)<=90&&abs($lng)<=180){$distance='(6371*ACOS(LEAST(1,COS(RADIANS(?))*COS(RADIANS(b.latitude))*COS(RADIANS(b.longitude)-RADIANS(?))+SIN(RADIANS(?))*SIN(RADIANS(b.latitude))))) distance_km';array_unshift($v,$lat,$lng,$lat);}$sort=$_GET['sort']??'relevance';$order=['rating'=>'rating DESC,reviews DESC','reviews'=>'reviews DESC,rating DESC','favorites'=>'favorites DESC,rating DESC','views'=>'views DESC,rating DESC','newest'=>'b.created_at DESC','name_az'=>'b.name ASC','name_za'=>'b.name DESC','nearest'=>'distance_km IS NULL,distance_km ASC','relevance'=>'b.created_at DESC'][$sort]??'b.created_at DESC';$q=$p->prepare('SELECT b.*,c.name category,COALESCE(AVG(r.rating),0) rating,COUNT(DISTINCT r.id) reviews,COUNT(DISTINCT f.user_id) favorites,(SELECT COUNT(*) FROM business_views bv WHERE bv.business_id=b.id) views,'.$distance.' FROM businesses b JOIN categories c ON c.id=b.category_id LEFT JOIN reviews r ON r.business_id=b.id AND r.status="visible" LEFT JOIN favorites f ON f.business_id=b.id WHERE '.implode(' AND ',$w).' GROUP BY b.id ORDER BY '.$order);$q->execute($v);return $q->fetchAll();}
function page_head(string $title,string $content):never{$u=user();$f=take_flash();$active=$_GET['page']??'home';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | Davao Local</title><link rel="stylesheet" href="style.css"><?php if(str_contains($content,'class="map-page"')):?><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><?php endif?><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap" rel="stylesheet"></head><body><header class="site-header"><div class="nav-container"><a class="brand" href="index.php" aria-label="Davao Local home"><span class="brand-mark">D</span><span>Davao <b>Local</b></span></a><button class="nav-toggle" type="button" aria-label="Toggle navigation" aria-expanded="false" aria-controls="site-navigation"><span></span><span></span><span></span></button><nav id="site-navigation" aria-label="Primary navigation"><?php if(is_role('customer')): ?><a class="<?=$active==='dashboard'?'active':''?>" href="customer.php">Dashboard</a><a class="<?=$active==='directory'?'active':''?>" href="?page=directory">Directory</a><a class="<?=$active==='map'?'active':''?>" href="?page=map">Map</a><a href="customer.php#saved">Saved</a><a class="<?=$active==='messages'?'active':''?>" href="messages.php">Messages</a><a class="<?=$active==='notifications'?'active':''?>" href="notifications.php">Notifications</a><a class="nav-logout" href="?action=logout">Log out</a><?php elseif($u): ?><a class="<?=$active==='directory'?'active':''?>" href="?page=directory">Directory</a><a class="<?=$active==='map'?'active':''?>" href="?page=map">Map</a><a class="<?=$active==='dashboard'?'active':''?>" href="?page=dashboard">Dashboard</a><a href="notifications.php">Notifications</a><a class="nav-logout" href="?action=logout">Log out</a><?php else: ?><a class="<?=$active==='directory'?'active':''?>" href="?page=directory">Directory</a><a class="<?=$active==='map'?'active':''?>" href="?page=map">Map</a><a class="<?=$active==='login'?'active':''?>" href="?page=login">Log in</a><a class="nav-cta" href="?page=register">Join us</a><?php endif?></nav></div></header><?php if($f):?><div class="flash <?=e($f[1])?>"><?=e($f[0])?></div><?php endif?><main><?=$content?></main><footer>© <?=date('Y')?> Davao Local Directory <span>Find local. Support local.</span></footer></body></html><?php exit;}
function card(PDO $p,array $b,bool $featured=false):void{$open=listing_open_now($p,$b);$services=array_slice(array_column(services($p,(int)$b['id']),'name'),0,3);$cover=null;if($featured){$photoQuery=$p->prepare("SELECT image_path FROM business_images WHERE business_id=? ORDER BY created_at DESC LIMIT 1");$photoQuery->execute([(int)$b['id']]);$cover=$photoQuery->fetchColumn();}?><article class="business-card <?= $featured?'featured-business-card':'' ?>"><?php if($featured):?><div class="featured-photo"><?php if($cover):?><img src="<?=e($cover)?>" alt="" loading="lazy"><?php else:?><img src="<?=e(category_photo($b['category']))?>" alt="" loading="lazy"><span class="photo-fallback-note">Representative category photo</span><?php endif?><span class="featured-photo-pin" aria-hidden="true">⌖</span></div><?php endif?><?php if($b['logo_path']):?><img class="card-logo" src="<?=e($b['logo_path'])?>" alt="<?=e($b['name'])?> logo"><?php else:?><div class="card-icon"><?=e(strtoupper($b['name'][0]))?></div><?php endif?><div class="card-content"><div class="card-top"><span class="pill"><?=e($b['category'])?></span><small class="approved">Approved listing</small><?php if((bool)$b['is_demo']):?><small class="demo-badge">Fictional demo</small><?php endif?><?php if($b['is_verified']):?><small class="verified">✓ Verified</small><?php endif?></div><h3><?=e($b['name'])?></h3><p><?=e(mb_strimwidth($b['description']??'',0,115,'…'))?></p><div class="details"><span>📍 <?=e($b['barangay']?:$b['city'])?></span><span>⭐ <?=number_format((float)$b['rating'],1)?> (<?=$b['reviews']?>)</span><span class="directory-status <?=$open?'is-open':'is-closed'?>">● <?=$open?'Open now':($b['business_status']==='temporarily_closed'?'Temporarily closed':($b['business_status']==='closed'?'Owner marked closed':'Closed'))?></span><?php if($b['distance_km']!==null):?><span>📍 <?=number_format((float)$b['distance_km'],1)?> km away</span><?php endif?></div><?php if($services):?><p class="services"><b>Services:</b> <?=e(implode(', ',$services))?></p><?php endif?><div class="card-actions"><a class="button light" href="?page=business&id=<?=$b['id']?>">View business</a><?php if(is_role('customer')):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="favorite"><input type="hidden" name="business_id" value="<?=$b['id']?>"><button class="link-button" aria-label="Save <?=e($b['name'])?>">♡ Save</button></form><?php endif?></div></div></article><?php }
if(($_GET['action']??'')==='logout'){session_destroy();session_start();flash('Logged out.');go('index.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';
if($a==='register'){$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$role=$_POST['role']??'customer';if(!$email||!trim($_POST['name']??'')||strlen($_POST['password']??'')<8||!in_array($role,['customer','owner'],true)){flash('Complete valid details; password needs 8 characters.','error');go('?page=register');}try{$pdo->prepare('INSERT INTO users(role_id,name,email,password_hash) VALUES(?,?,?,?)')->execute([$role==='owner'?2:1,mb_strimwidth(trim($_POST['name']),0,100,''),$email,password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('Account created. Please log in.');}catch(PDOException){flash('Email already exists.','error');}go('?page=login');}
if($a==='login'){$q=$pdo->prepare('SELECT u.id,u.name,u.email,u.password_hash,r.name role,u.status FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=?');$q->execute([trim($_POST['email']??'')]);$x=$q->fetch();if($x&&$x['status']==='active'&&password_verify($_POST['password']??'',$x['password_hash'])){unset($x['password_hash'],$x['status']);$_SESSION['user']=$x;$pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$x['id']]);go('?page=dashboard');}flash('Incorrect email or password.','error');go('?page=login');}
if(!logged_in()){flash('Please log in first.','error');go('?page=login');}
if($a==='review'&&is_role('customer')){$id=(int)$_POST['business_id'];$text=mb_strimwidth(trim($_POST['comment']??''),0,3000,'');$q=$pdo->prepare('SELECT owner_id FROM businesses WHERE id=? AND status="approved"');$q->execute([$id]);$owner=(int)$q->fetchColumn();if(!$owner||!$text){flash('Write a review first.','error');go('?page=business&id='.$id);}$pdo->prepare('INSERT INTO reviews(business_id,user_id,rating,comment)VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment)')->execute([$id,user()['id'],max(1,min(5,(int)$_POST['rating'])),$text]);notify_user($pdo,$owner,'You received a new customer review.','owner_reviews.php','review');go('?page=business&id='.$id);}
if($a==='review_delete'&&is_role('customer')){$pdo->prepare('DELETE FROM reviews WHERE id=? AND user_id=?')->execute([(int)$_POST['review_id'],user()['id']]);flash('Review deleted.');go('?page=business&id='.(int)$_POST['business_id']);}
if($a==='review_report'&&is_role('customer')){$review=(int)$_POST['review_id'];$reason=mb_strimwidth(trim($_POST['reason']??''),0,255,'');if($reason){$pdo->prepare('INSERT INTO review_reports(review_id,user_id,reason) VALUES(?,?,?) ON DUPLICATE KEY UPDATE reason=VALUES(reason),status="pending"')->execute([$review,user()['id'],$reason]);flash('Review report submitted.');}go('?page=business&id='.(int)$_POST['business_id']);}
if($a==='favorite'&&is_role('customer')){$id=(int)($_POST['business_id']??0);$q=$pdo->prepare('SELECT id FROM businesses WHERE id=? AND status="approved"');$q->execute([$id]);if(!$q->fetchColumn()){flash('This listing is no longer available.','error');go('?page=directory');}$q=$pdo->prepare('DELETE FROM favorites WHERE user_id=? AND business_id=?');$q->execute([user()['id'],$id]);if(!$q->rowCount()){ $pdo->prepare('INSERT INTO favorites(user_id,business_id) VALUES(?,?)')->execute([user()['id'],$id]);flash('Business saved to your favorites.');}else{flash('Business removed from your favorites.');}go('?page=business&id='.$id);}
if($a==='inquiry'&&is_role('customer')){$id=(int)($_POST['business_id']??0);$sub=mb_strimwidth(trim($_POST['subject']??''),0,150,'');$msg=mb_strimwidth(trim($_POST['message']??''),0,3000,'');$q=$pdo->prepare('SELECT owner_id FROM businesses WHERE id=? AND status="approved"');$q->execute([$id]);$owner=(int)$q->fetchColumn();if(!$owner||!$sub||!$msg){flash('Complete the inquiry.','error');go('?page=business&id='.$id);}$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO inquiries(business_id,user_id,subject,message)VALUES(?,?,?,?)')->execute([$id,user()['id'],$sub,$msg]);$pdo->prepare('INSERT INTO conversations(business_id,customer_id,owner_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),owner_id=VALUES(owner_id),updated_at=NOW()')->execute([$id,user()['id'],$owner]);$conversationId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO messages(conversation_id,sender_id,receiver_id,message) VALUES(?,?,?,?)')->execute([$conversationId,user()['id'],$owner,$sub."\n".$msg]);$pdo->commit();notify_user($pdo,$owner,'You have a new business inquiry.','messages.php?conversation='.$conversationId,'inquiry');flash('Inquiry sent. Continue the conversation in Messages.');go('messages.php?conversation='.$conversationId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('The inquiry could not be sent. Please try again.','error');go('?page=business&id='.$id);}}}
if($page==='home'){$homeSort=$_GET['sort']??null;$_GET['sort']='views';$rows=array_slice(list_businesses($pdo),0,6);if($homeSort===null)unset($_GET['sort']);else $_GET['sort']=$homeSort;$categories=cats($pdo);$categoryCounts=$pdo->query("SELECT category_id,COUNT(*) total FROM businesses WHERE status='approved' GROUP BY category_id")->fetchAll(PDO::FETCH_KEY_PAIR);ob_start();?><section class="hero home-hero"><div class="hero-copy"><p class="eyebrow">DAVAO CITY LOCAL DIRECTORY</p><h1>Find nearby <em>local favorites.</em></h1><p class="hero-text">Explore trusted businesses, useful services, and places worth discovering around Davao.</p><form class="quick-search home-directory-search" action="index.php" method="get"><input type="hidden" name="page" value="directory"><label class="home-search-field"><span aria-hidden="true">⌕</span><input name="q" aria-label="Search local businesses" placeholder="What are you looking for?"></label><label class="home-location-field"><span aria-hidden="true">⌖</span><input name="area" aria-label="Location or barangay" placeholder="Location or barangay" value="Davao City"></label><label class="home-category-field"><span aria-hidden="true">▦</span><select name="category" aria-label="All categories"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?=(int)$category['id']?>"><?=e($category['name'])?></option><?php endforeach?></select></label><button class="button coral">Search <span aria-hidden="true">→</span></button></form><div class="home-popular"><b>Popular:</b><?php foreach(array_slice($categories,0,5) as $category):?><a href="?page=directory&category=<?=(int)$category['id']?>"><?=e($category['name'])?></a><?php endforeach?></div></div><div class="home-city-photo"><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Mount_Apo_view_from_Aeon_Tower_%28Davao_City%3B_11-26-2021%29.jpg/1280px-Mount_Apo_view_from_Aeon_Tower_%28Davao_City%3B_11-26-2021%29.jpg" alt="Davao City and Mount Apo"><a href="https://commons.wikimedia.org/wiki/File:Mount_Apo_view_from_Aeon_Tower_(Davao_City;_11-26-2021).jpg" target="_blank" rel="noopener">Photo: Patrick Roque · CC BY-SA 4.0</a></div></section><section class="home-categories home-popular-categories"><div class="home-section-heading"><p class="eyebrow">BROWSE DAVAO</p><h2>Popular categories</h2><p>Start with what you need and find a local business that fits.</p></div><div class="category-links home-category-grid"><?php foreach($categories as $category):?><a class="home-category-card" href="?page=directory&category=<?=(int)$category['id']?>"><img src="<?=e(category_photo($category['name']))?>" alt="" loading="lazy"><span class="category-card-caption"><b><?=e($category['name'])?></b><small><?= (int)($categoryCounts[$category['id']]??0) ?> businesses</small><?php if($category['name']==='Printing Services'):?><small class="photo-credit">Photo: Stephany5757 · CC BY-SA 4.0</small><?php endif?></span></a><?php endforeach?></div></section><section class="directory home-featured"><div class="section-title"><div><p class="eyebrow">DAVAO LOCAL PICKS</p><h2>Most visited listings</h2><p class="home-featured-intro">A few neighborhood favorites to get you started.</p></div><a class="button dark" href="?page=directory">View all listings <span aria-hidden="true">→</span></a></div><div class="cards"><?php foreach($rows as $b)card($pdo,$b,true);if(!$rows):?><div class="empty"><h2>New directory, ready to grow</h2><p>There are no approved listings to show yet. Browse the directory or create an owner account to submit a listing for review.</p><a class="button light" href="?page=directory">Browse directory</a></div><?php endif?></div></section><section class="how home-how"><p class="eyebrow">HOW IT WORKS</p><h2>Find a listing. Check the details. Reach out.</h2><div class="steps"><article><span>01</span><h3>Search the directory</h3><p>Use a keyword, category, or area to narrow the approved listings.</p></article><article><span>02</span><h3>Review the profile</h3><p>Check the services, hours, location details, and any customer reviews provided.</p></article><article><span>03</span><h3>Contact the owner</h3><p>Send an inquiry or request an appointment after signing in.</p></article></div><p class="home-approval-note">Approval allows a listing to appear publicly. Verification is a separate admin-set status. Sample listings are fictional and labeled.</p></section><section class="home-owner-cta"><div><p class="eyebrow">FOR DAVAO BUSINESS OWNERS</p><h2>Manage your listing in one place.</h2><p>Submit your business for admin review, then maintain your profile, hours, and services.</p></div><a class="button dark" href="?page=register">Create an owner account <span aria-hidden="true">→</span></a></section><?php page_head('Davao Local',ob_get_clean());}if($page==='directory'){$rows=list_businesses($pdo);$active=[];$labels=['q'=>'Search: ','area'=>'Area: ','rating'=>'','verified'=>'Verified','open'=>'Open now','contact'=>'Has contact','map'=>'Has map','services'=>'Has services','price_min'=>'Min ₱','price_max'=>'Max ₱'];foreach($labels as $key=>$prefix){if(($_GET[$key]??'')!==''&&($_GET[$key]??'')!=='0')$active[$key]=$key==='rating'?$_GET[$key].'+ stars':$prefix.($_GET[$key]==='1'?'':$_GET[$key]);}$categoryId=(int)($_GET['category']??0);$categoryRows=cats($pdo);$selectedCategory=null;$categoryCounts=$pdo->query("SELECT category_id,COUNT(*) total FROM businesses WHERE status='approved' GROUP BY category_id")->fetchAll(PDO::FETCH_KEY_PAIR);if($categoryId){foreach($categoryRows as $c)if((int)$c['id']===$categoryId){$active['category']=$c['name'];$selectedCategory=$c;}}ob_start();?><section class="directory page"><div class="directory-hero"><div class="directory-hero-copy"><p class="eyebrow">LOCAL BUSINESS DIRECTORY · DAVAO CITY</p><h1>Explore the great places <em>around you.</em></h1><p>Find trusted neighborhood businesses, everyday services, and local favorites across Davao.</p><a class="directory-hero-link" href="#directory-results">Explore local listings <span aria-hidden="true">→</span></a></div><div class="directory-city-photo"><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Davao_from_air%2C_Lanang%2C_Agdao_%28Davao_City%3B_11-24-2021%29.jpg/1280px-Davao_from_air%2C_Lanang%2C_Agdao_%28Davao_City%3B_11-24-2021%29.jpg" alt="Aerial view of the Lanang commercial district in Davao City" loading="eager"><a href="https://commons.wikimedia.org/wiki/File:Davao_from_air,_Lanang,_Agdao_(Davao_City;_11-24-2021).jpg" target="_blank" rel="noopener">Photo: Patrick Roque · CC BY-SA 4.0</a></div></div><p class="directory-intro-label">FIND A DAVAO BUSINESS</p><h2 class="directory-search-title">What are you looking for?</h2><form class="directory-filters" id="directory-filters"><input type="hidden" name="page" value="directory"><input type="hidden" name="lat" value="<?=e($_GET['lat']??'')?>"><input type="hidden" name="lng" value="<?=e($_GET['lng']??'')?>"><label class="filter-search"><span>Search</span><span class="search-input">⌕ <input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Business, product, service, or description"></span></label><label><span>Category</span><select name="category"><option value="">All categories</option><?php foreach(cats($pdo) as $c):?><option value="<?=$c['id']?>" <?=($categoryId===$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><label><span>Area / barangay</span><input name="area" value="<?=e($_GET['area']??'')?>" placeholder="Any area"></label><label><span>Rating</span><select name="rating"><option value="">Any rating</option><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>" <?=((int)($_GET['rating']??0)===$i)?'selected':''?>><?=$i?> stars+</option><?php endfor?></select></label><div class="filter-options"><label><input type="checkbox" name="verified" value="1" <?=($_GET['verified']??'')==='1'?'checked':''?>> Verified only</label><label><input type="checkbox" name="open" value="1" <?=($_GET['open']??'')==='1'?'checked':''?>> Open now</label><label><input type="checkbox" name="contact" value="1" <?=($_GET['contact']??'')==='1'?'checked':''?>> Has contact</label><label><input type="checkbox" name="map" value="1" <?=($_GET['map']??'')==='1'?'checked':''?>> Has map</label><label><input type="checkbox" name="services" value="1" <?=($_GET['services']??'')==='1'?'checked':''?>> Available services</label></div><label><span>Price range</span><span class="price-range"><input type="number" min="0" step=".01" name="price_min" value="<?=e($_GET['price_min']??'')?>" placeholder="Min"><input type="number" min="0" step=".01" name="price_max" value="<?=e($_GET['price_max']??'')?>" placeholder="Max"></span></label><label><span>Sort by</span><select name="sort"><option value="relevance">Relevance</option><option value="rating" <?=($_GET['sort']??'')==='rating'?'selected':''?>>Highest rated</option><option value="reviews" <?=($_GET['sort']??'')==='reviews'?'selected':''?>>Most reviewed</option><option value="favorites" <?=($_GET['sort']??'')==='favorites'?'selected':''?>>Most favorited</option><option value="nearest" <?=($_GET['sort']??'')==='nearest'?'selected':''?>>Nearest</option><option value="newest" <?=($_GET['sort']??'')==='newest'?'selected':''?>>Newest</option><option value="name_az" <?=($_GET['sort']??'')==='name_az'?'selected':''?>>A–Z</option><option value="name_za" <?=($_GET['sort']??'')==='name_za'?'selected':''?>>Z–A</option></select></label><div class="filter-actions"><button class="button coral">Apply filters</button><button type="button" class="button light" data-clear-filters>Clear filters</button><button type="button" class="near-me" data-near-me>📍 Near me</button></div></form><?php if($active):?><div class="active-filters"><span>Showing results for:</span><?php foreach($active as $key=>$label):?><a href="?<?=e(http_build_query(array_diff_key($_GET,[$key=>true])))?>" class="filter-chip"><?=e($label)?> <b aria-label="Remove filter">×</b></a><?php endforeach?><a class="clear-all" href="?page=directory">Clear all</a></div><?php endif?><p class="demo-notice" role="note">Some listings are fictional demo data for testing and do not represent real businesses. Look for the Fictional demo label.</p><div class="directory-listing-heading" id="directory-results"><p class="eyebrow">DAVAO LOCAL PICKS</p><h2>Businesses near you.</h2></div><div class="result-summary"><p><b><?=count($rows)?> businesses found</b></p><?php if($categoryId&&isset($active['category'])):?><p>Showing results for: <?=e($active['category'])?></p><?php endif?></div><div class="cards"><?php foreach($rows as $b)card($pdo,$b);?><?php if(!$rows):?><?php if($selectedCategory):?><div class="category-empty-state"><img src="<?=e(category_photo($selectedCategory['name']))?>" alt="" loading="lazy"><div><p class="eyebrow"><?=e($selectedCategory['name'])?></p><?php if($selectedCategory['name']==='Printing Services'):?><p class="photo-credit-text"><a href="https://commons.wikimedia.org/wiki/File:Kevin,_a_large_format_printer_operator.jpg" target="_blank" rel="noopener">Photo: Stephany5757 · CC BY-SA 4.0</a></p><?php endif?><h2>No businesses listed in this category yet.</h2><p>We’re still building this part of the Davao Local directory. Explore another category or view all approved listings.</p><a class="button dark" href="?page=directory">Explore the directory</a><a class="category-empty-link" href="#browse-categories">Browse other categories</a></div></div><?php else:?><div class="empty"><h2>No businesses found</h2><p>Try changing or clearing your filters.</p><a class="button light" href="?page=directory">Clear filters</a></div><?php endif?><?php endif?></div><div class="directory-category-block"><div class="directory-category-heading"><div><p class="eyebrow">BROWSE BY CATEGORY</p><h2>Find your kind of place.</h2></div><a href="?page=directory">All businesses <span aria-hidden="true">→</span></a></div><div class="directory-category-grid" id="browse-categories"><?php foreach($categoryRows as $category):?><a class="directory-category-card" href="?page=directory&category=<?=(int)$category['id']?>"><img src="<?=e(category_photo($category['name']))?>" alt="" loading="lazy"><span class="category-card-caption"><b><?=e($category['name'])?></b><small><?= (int)($categoryCounts[$category['id']]??0) ?> businesses</small><?php if($category['name']==='Printing Services'):?><small class="photo-credit">Photo: Stephany5757 · CC BY-SA 4.0</small><?php endif?></span></a><?php endforeach?></div></div></section><?php page_head('Directory',ob_get_clean());}
