if($page==='business'){$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT b.*,c.name category,COALESCE(AVG(r.rating),0) rating,COUNT(r.id) reviews FROM businesses b JOIN categories c ON c.id=b.category_id LEFT JOIN reviews r ON r.business_id=b.id AND r.status="visible" WHERE b.id=? AND b.status="approved" GROUP BY b.id');$q->execute([$id]);$b=$q->fetch();if(!$b)page_head('Not found','<section class="directory page"><h1>Business not found.</h1></section>');$pdo->prepare('INSERT INTO business_views(business_id,user_id) VALUES(?,?)')->execute([$id,user()['id']??null]);$q=$pdo->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.business_id=? AND r.status="visible" ORDER BY r.created_at DESC');$q->execute([$id]);$reviews=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM business_hours WHERE business_id=?');$q->execute([$id]);$hours=array_column($q->fetchAll(),null,'day_of_week');$q=$pdo->prepare('SELECT * FROM business_images WHERE business_id=? ORDER BY created_at DESC');$q->execute([$id]);$images=$q->fetchAll();$sv=services($pdo,$id);$productQuery=$pdo->prepare("SELECT * FROM products WHERE business_id=? AND availability='available' ORDER BY is_featured DESC,name LIMIT 30");$productQuery->execute([$id]);$products=$productQuery->fetchAll();ob_start();?><section class="profile"><p class="eyebrow"><?=e($b['category'])?></p><div class="profile-head"><?php if($b['logo_path']):?><img class="profile-logo" src="<?=e($b['logo_path'])?>" alt=""><?php endif?><div><h1><?=e($b['name'])?><small class="approved">Approved listing</small><?php if((bool)$b['is_demo']):?><small class="demo-badge">Fictional demo</small><?php endif?><?php if($b['is_verified']):?> <small class="verified">✓ Verified business</small><?php endif?></h1><p><?=e($b['description'])?></p><span class="rating">★ <?=number_format((float)$b['rating'],1)?> <small>(<?=$b['reviews']?> reviews)</small></span><p><b><?=listing_open_now($pdo,$b)?'Open now':($b['business_status']==='temporarily_closed'?'Temporarily closed':($b['business_status']==='closed'?'Owner marked closed':'Closed'))?></b></p></div><div class="actions"><?php if(is_role('customer')):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="favorite"><input type="hidden" name="business_id" value="<?=$id?>"><button class="button dark">♡ Save</button></form><?php endif?><?php if(!(bool)$b['is_demo']&&$b['latitude']!==null&&$b['longitude']!==null&&(float)$b['latitude']>=-90&&(float)$b['latitude']<=90&&(float)$b['longitude']>=-180&&(float)$b['longitude']<=180):?><a class="button coral" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=<?=e((string)$b['latitude'])?>&mlon=<?=e((string)$b['longitude'])?>">Directions</a><?php else:?><span class="location-unavailable">No saved map location</span><?php endif?></div></div><div class="profile-grid"><div><?php if($images):?><article class="info-box"><h2>Gallery</h2><div class="gallery-grid"><?php foreach($images as $im):?><figure><img src="<?=e($im['image_path'])?>" alt="<?=e($im['caption'])?>"><figcaption><?=e($im['caption'])?></figcaption></figure><?php endforeach?></div></article><?php endif?><article class="info-box"><h2>Services</h2><?php foreach($sv as $s):?><p><b><?=e($s['name'])?></b><?= $s['price']!==null?' · ₱'.number_format((float)$s['price'],2):''?><br><?=e($s['description'])?></p><?php endforeach?></article><?php if($products):?><article class="info-box"><h2>Products</h2><?php foreach($products as $product):?><div class="profile-product"><h3><?=e($product['name'])?></h3><?php if($product['price']!==null):?><p class="product-price">₱<?=number_format((float)$product['price'],2)?></p><?php endif?><?php if($product['description']):?><p><?=e($product['description'])?></p><?php endif?></div><?php endforeach?></article><?php endif?><article class="info-box"><h2>Reviews</h2><?php foreach($reviews as $r):?><div class="review"><b><?=e($r['name'])?></b> <span class="rating">★ <?=$r['rating']?></span> <small><?=e(date('M j, Y',strtotime($r['created_at'])))?></small><p><?=e($r['comment'])?></p><?php if($r['response']):?><p><b>Owner reply:</b> <?=e($r['response'])?></p><?php endif?><?php if(is_role('customer')&&$r['user_id']==user()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review_delete"><input type="hidden" name="review_id" value="<?=$r['id']?>"><input type="hidden" name="business_id" value="<?=$id?>"><button class="danger">Delete my review</button></form><?php endif?></div><?php endforeach?><?php if(is_role('customer')):?><form method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review"><input type="hidden" name="business_id" value="<?=$id?>"><select name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> stars</option><?php endfor?></select><textarea required maxlength="3000" name="comment" placeholder="Write or update your review"></textarea><button class="button coral">Save review</button></form><?php endif?></article></div><aside class="contact-box"><h2>Contact information</h2><p>☎ <?=e($b['contact_phone'])?></p><p>✉ <?=e($b['contact_email'])?></p><p>⌖ <?=e($b['address'])?>, <?=e($b['barangay'])?>, <?=e($b['city'])?></p><h3>Weekly schedule</h3><?php foreach(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $d=>$name):$h=$hours[$d]??null;?><p><?=e($name)?>: <?=(!$h||$h['is_closed'])?'Closed':e(substr($h['opens'],0,5).'–'.substr($h['closes'],0,5))?></p><?php endforeach?><?php if(is_role('customer')):?><hr><h3>Send inquiry</h3><form method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="inquiry"><input type="hidden" name="business_id" value="<?=$id?>"><input required maxlength="150" name="subject" placeholder="Subject"><textarea required maxlength="3000" name="message" placeholder="Your message"></textarea><button class="button dark">Send inquiry</button></form><hr><h3>Book appointment</h3><form action="appointments.php" method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="book"><input type="hidden" name="business_id" value="<?=$id?>"><select name="service_id"><option value="">Select a service</option><?php foreach($sv as $s):?><option value="<?=$s['service_id']?>"><?=e($s['name'])?></option><?php endforeach?></select><input required type="datetime-local" name="appointment_at" min="<?=date('Y-m-d\\TH:i')?>"><textarea name="notes" maxlength="2000" placeholder="Optional notes"></textarea><button class="button coral">Request appointment</button></form><hr><h3>Report business</h3><form action="reports.php" method="post" class="mini-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="business_id" value="<?=$id?>"><select required name="reason"><option value="">Choose reason</option><option value="fake_business">Fake business</option><option value="wrong_information">Wrong information</option><option value="inappropriate_content">Inappropriate content</option><option value="duplicate_listing">Duplicate listing</option><option value="closed_business">Closed business</option><option value="other">Other</option></select><textarea name="details" maxlength="3000" placeholder="Optional details"></textarea><button class="link-button">Submit report</button></form><?php endif?></aside></div></section><?php page_head($b['name'],ob_get_clean());}
