if($page==='map'){
    // Map only owner-entered coordinates for approved, non-sample Davao City listings.
    $mapRows=$pdo->query("SELECT id,name,latitude,longitude FROM businesses WHERE status='approved' AND is_demo=0 AND city='Davao City' AND latitude IS NOT NULL AND longitude IS NOT NULL AND latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180 ORDER BY name")->fetchAll();
    $notMapped=(int)$pdo->query("SELECT COUNT(*) FROM businesses WHERE status='approved' AND (is_demo=1 OR city IS NULL OR city<>'Davao City' OR latitude IS NULL OR longitude IS NULL OR latitude NOT BETWEEN -90 AND 90 OR longitude NOT BETWEEN -180 AND 180)")->fetchColumn();
    $markers=array_map(static fn($b)=>['id'=>(int)$b['id'],'name'=>$b['name'],'lat'=>(float)$b['latitude'],'lng'=>(float)$b['longitude']],$mapRows);
    $markerJson=json_encode($markers,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);
    ob_start();
    ?>
    <section class="directory page map-page">
      <p class="eyebrow">DAVAO LOCAL DIRECTORY</p><h1>Businesses on the map</h1>
      <p class="map-intro">Markers show approved, non-sample Davao City listings using coordinates saved for that business. Select a marker to open its profile.</p>
      <p class="map-notice" role="note"><?=count($mapRows)?> mapped listings · <?=$notMapped?> approved listings are excluded because they are samples or have no usable saved location. <a href="?page=directory">Browse all approved listings</a>.</p>
      <div class="map-tools"><button class="button light" type="button" id="map-locate">Use my location</button><span id="map-status" role="status" aria-live="polite">The map uses OpenStreetMap tiles and needs an internet connection.</span></div>
      <div id="directory-map" class="directory-map" role="region" aria-label="Map of approved Davao Local businesses"></div>
      <?php if($mapRows):?><section class="map-results"><h2>Mapped businesses</h2><ol><?php foreach($mapRows as $b):?><li><a href="?page=business&amp;id=<?=(int)$b['id']?>"><?=e($b['name'])?></a></li><?php endforeach?></ol></section><?php else:?><div class="empty map-empty"><h2>No real listings are mapped yet</h2><p>The map is centered on Davao City. Approved sample listings stay off the map; an owner must save a usable Davao City location before a listing appears here.</p><a class="button light" href="?page=directory">Browse the directory</a></div><?php endif?>
      <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
      <script>(function(){const markers=<?=$markerJson?>,status=document.getElementById('map-status'),root=document.getElementById('directory-map');if(!window.L){root.hidden=true;status.textContent='The map library could not load. Use the mapped-business links below or browse the directory.';return;}const davao=[7.0731,125.6128],map=L.map(root,{scrollWheelZoom:false}),osm=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);let loaded=false;osm.on('tileload',function(){loaded=true;status.textContent=markers.length?'Map ready. Select a marker or its link below to view a business.':'Map centered on Davao City. No eligible real listings have saved map coordinates yet.';});osm.on('tileerror',function(){if(!loaded)status.textContent='Map tiles could not load. Check your internet connection; mapped-business links remain available below.';});if(markers.length){const points=[];markers.forEach(function(item){const point=[item.lat,item.lng],url='?page=business&id='+encodeURIComponent(item.id);points.push(point);const marker=L.marker(point,{title:item.name,alt:'Open '+item.name+' profile'}).addTo(map),link=document.createElement('a');link.href=url;link.textContent='Open '+item.name+' profile';marker.bindPopup(link);});if(points.length===1)map.setView(points[0],14);else map.fitBounds(points,{padding:[28,28],maxZoom:14});}else{map.setView(davao,12);}document.getElementById('map-locate').addEventListener('click',function(){if(!navigator.geolocation){status.textContent='Location is unavailable in this browser. You can still use the Davao map and directory.';return;}status.textContent='Requesting your location…';navigator.geolocation.getCurrentPosition(function(position){map.setView([position.coords.latitude,position.coords.longitude],13);status.textContent='Map centered on your current location. Your location is not saved.';},function(){status.textContent='Location access was unavailable. The map stays centered on Davao City.';},{timeout:10000,maximumAge:60000});});setTimeout(function(){if(!loaded)status.textContent='Map tiles are taking too long or are unavailable. Check your internet connection; mapped-business links remain below.';},8000);})();</script>
    </section>
    <?php page_head('Map',ob_get_clean());
}
